insert into public.courses (slug, sort, name, level, duration, scope, price_from_eur, price_unit, photo_id, photo_alt, summary, description, learn, requirements, certificate, theory) values
('vhf-radio-operator',1,'IYT VHF Radio Operator','All crew','1 day','Needed for all crew',190,'per person','1769724839524-ea4bd870f813','A marine VHF radio at a yacht''s chart table','The radio licence every crew member needs.','A one-day course on the marine VHF radio: how to call a marina or another yacht, how to send and answer distress, urgency and safety calls, and how DSC works. You practise on real radio sets and finish with the exam for the IYT VHF Radio Operator certificate.',array['Channel 16, working channels and dual watch','Mayday, Pan-Pan and Sécurité calls','DSC distress alerts and the MMSI number','The phonetic alphabet and procedure words']::text[],array['No sailing experience needed','Age 16 or over','Enough English to follow standard radio phrases; we explain each one']::text[],'Lets you operate a marine VHF radio, DSC included, on a yacht. Valid for 5 years, then you renew it. Most charter companies ask for at least one person aboard with this licence.',array['vhf-procedure']::text[]),
('introduction-to-yachting',2,'IYT Introduction to Yachting','Beginner','5 days','No experience needed',990,'per person','1562862076-42e207f5561e','Friends smiling on the bow of a sailing yacht','For beginners: helm, ropes, knots, life on board.','Five days living aboard with an instructor, for people who have never sailed. You learn to steer, trim the sails, handle lines and fenders, tie the knots you need, and help with mooring and anchoring. It ends with the IYT International Crew certificate, the first step towards skippering.',array['Steering under sail and under engine','Trimming the sails on every point of sail','Knots, lines, fenders and winches','Your role when mooring and anchoring','Basic rules of the road and the weather forecast','Engine checks and handling the dinghy','Man overboard and safety on board']::text[],array['No experience needed','Able to swim','Age 16 or over; younger sailors can join with a parent aboard, ask us first','Fit enough to step on and off a boat and move around the deck']::text[],'IYT International Crew: active crew on yachts up to 24 m, up to 20 nm offshore, by day and in fair weather. It is the first step on the IYT ladder and the entry requirement for Flotilla and Bareboat Skipper.',array['points-of-sail','knots']::text[]),
('international-flotilla-skipper',3,'IYT International Flotilla Skipper','Flotilla skipper','5 days','Up to 20 nm offshore',1290,'per person','1776347652659-6645d9532767','A skipper at the helm of a catamaran in a turquoise bay','Skipper a charter yacht in a group with a lead boat.','A five-day course for people with some crew experience who want to skipper their own yacht in a flotilla, with a lead boat nearby. You plan short daily passages, moor in busy harbours and anchor in bays, by day and in fair weather.',array['Taking command and briefing a crew','Planning the day''s passage','Mediterranean mooring and anchoring','Checking the weather before you leave','Charts, buoyage and the rules of the road']::text[],array['IYT International Crew or an equivalent certificate','VHF licence, IYT or equivalent (can be taken the same week)','Age 16 or over','Able to swim']::text[],'IYT International Flotilla Skipper: command of a sailing yacht up to 24 m as part of a flotilla, up to 20 nm offshore, in fair weather. Most charter companies only allow sailing by day. You can also get the ICC with it.',array['med-mooring','anchoring','right-of-way']::text[]),
('bareboat-skipper',4,'IYT International Bareboat Skipper','Bareboat skipper','5 days','Up to 20 nm offshore',1490,'per person','1780335282813-db330424b1bd','A skipper at the wheel leaving harbour','Charter a yacht on your own: mooring, anchoring, navigation.','A week living aboard to learn everything you need to charter a yacht without a professional skipper.',array[]::text[],array[]::text[],'',array[]::text[]),
('icc',5,'ICC','Bareboat skipper','Half a day','Valid 5 years',150,'exam','1542405242-8217b4c9e34c','A crew in life jackets on deck','The licence most European waters ask for, sail or power.','The International Certificate of Competence is accepted in many European coastal waters, and on inland waterways if you also pass the CEVNI exam. You can get it on the basis of a qualifying certificate such as IYT Bareboat Skipper, or by taking a written and a practical exam with us. It is valid for five years.',array['Practical assessment under engine and under sail','Rules of the road and navigation lights','The CEVNI exam for the inland waterways endorsement','Safety equipment and emergency procedures']::text[],array['A qualifying IYT skipper certificate, or the written and practical exams','VHF licence','Age 16 or over','Not a citizen of a country that issues its own ICC (we check this with you)','Passport or ID card and a headshot photo']::text[],'ICC: proof of competence for chartering in much of Europe. Check what the country you plan to sail in accepts.',array['right-of-way','navigation-lights']::text[]),
('yachtmaster-coastal',6,'IYT Yachtmaster Coastal','Coastal skipper','6 days','Up to 60 nm offshore',1890,'per person','1777880652014-feee433c6be0','A sailor in a foul-weather jacket at the mast','Command yachts up to 24 m, by day and night.','For experienced skippers who want to take a yacht up to 60 nautical miles offshore, by day and by night. The week aboard sharpens passage planning, night navigation, heavy-weather handling and crew management, and ends with written, oral and practical exams.',array['Planning longer passages','Night navigation and keeping watch','Heavy-weather tactics and reefing','Emergency drills: man overboard, fire, engine failure','Tides, the collision rules and chartwork']::text[],array['800 miles and 25 days at sea, including 2 days as skipper or watch leader, before the exam','12 hours of sailing at night','Age 18 or over']::text[],'IYT Yachtmaster Coastal: command of yachts up to 24 m, up to 60 nm offshore, in moderate weather. For private use only: it is not a commercial licence and cannot be upgraded to one.',array['position-fixing','weather','navigation-lights']::text[]),
('yachtmaster-offshore',7,'IYT Yachtmaster Offshore','Yachtmaster','11 days','Up to 150 nm offshore',2690,'per person','1732267994253-4b9e4fd70a41','A crew in sailing jackets on deck in open water','Long passages out of sight of land.','Five days of theory and six days at sea for skippers ready to take a yacht far from land, up to 150 nautical miles offshore. You run passages with a full watch system, navigate without electronics, and look after crew and boat over several days. Our training passages along the Turkish coast are the easiest way to build the miles you need.',array['Planning and provisioning an offshore passage','Navigating without a chartplotter','Watch systems and crew management','Weather routing over several days']::text[],array['3,000 miles and 50 days at sea, at least 2,000 miles of them along coasts','30 hours on watch at night, 6 of them as skipper or watch leader','VHF licence, a medical certificate and an eyesight test for colour blindness','Age 18 or over','STCW Basic Safety recommended, not required']::text[],'IYT Yachtmaster Offshore: command of yachts up to 24 m, up to 150 nm offshore. For private use only: it is not a commercial licence and cannot be upgraded to one.',array['position-fixing','weather']::text[]),
('yachtmaster-ocean',8,'IYT Yachtmaster Ocean','Yachtmaster','6 days of theory','Any ocean',890,'per person','1764726411645-744d48aa4497','A sextant, watch and dividers on a chart','Celestial navigation with a sextant, anywhere in the world.','The highest IYT recreational certificate. The course teaches celestial navigation: taking sights with a sextant, working out your position from the sun and stars, and planning ocean passages. It is open to holders of Yachtmaster Offshore.',array['Using a sextant','Sun and star sights','Working out and plotting a position','Planning an ocean passage','Checking the compass by the sun and stars','Great circle routes and ocean weather']::text[],array['IYT Yachtmaster Offshore','Age 18 or over']::text[],'IYT Yachtmaster Ocean: command of yachts up to 24 m anywhere in the world, navigating by sextant. For private use only; not a commercial licence.',array['position-fixing']::text[])
